import{_ as a,o as n,c as t,a3 as i}from"./chunks/framework.MGD2uYU7.js";const g=JSON.parse('{"title":"SC-23 — Tin của tôi","description":"","frontmatter":{"title":"SC-23 — Tin của tôi"},"headers":[],"relativePath":"wireframes/user/sc-23-tin-cua-toi.md","filePath":"wireframes/user/sc-23-tin-cua-toi.md","lastUpdated":1791606799000}'),l={name:"wireframes/user/sc-23-tin-cua-toi.md"};function c(p,s,d,e,o,h){return n(),t("div",null,[...s[0]||(s[0]=[i('<h1 id="sc-23-—-tin-cua-toi-quan-ly-tin-đang" tabindex="-1">SC-23 — Tin của tôi (quản lý tin đăng) <a class="header-anchor" href="#sc-23-—-tin-cua-toi-quan-ly-tin-đang" aria-label="Permalink to &quot;SC-23 — Tin của tôi (quản lý tin đăng)&quot;">​</a></h1><p><span class="wf-badge info">Route: /tin-cua-toi</span> <span class="wf-badge muted">Guard: USER · Nguồn: docs/05 §3 SC-23 · docs/03 UC-05 · docs/02 FR-HS · docs/08 BR-HS · docs/07 §3</span></p><p><strong>Ai xem màn này</strong>: Chủ nhà (thành viên KYC APPROVED) quản lý tin của chính mình — mọi trạng thái. Không phải màn admin (duyệt tin là SC-42). <strong>Mục đích / cảm xúc thiết kế</strong>: bảng điều khiển tin đăng — nhìn 1 lần biết ngay tin nào đang ở đâu trong vòng đời (nháp → chờ duyệt → đang bán → đấu giá → đã bán), tin nào cần hành động (bị từ chối, hết hạn quota), và <strong>hậu quả thật</strong> trước mỗi thao tác không thể đảo ngược (rút tin). <strong>Ví dụ số dùng trong bản vẽ</strong>: <code>Nguyễn Văn Demo</code> (NĐ) — 4 tin tại dự án NOXH <code>HP-380</code>: LISTED căn <code>AB-05.02</code> giá <code>1.250.000.000 ₫</code> · IN_REVIEW căn <code>CT1-B02.11</code> · DRAFT căn <code>CD-03.06</code> · REJECTED căn <code>BA-07.01</code>; gói FREE hạn mức 1/2 tin đang bán.</p><h2 id="_1-desktop-—-tabs-theo-trang-thai-bang-tin" tabindex="-1">1. Desktop — tabs theo trạng thái + bảng tin <a class="header-anchor" href="#_1-desktop-—-tabs-theo-trang-thai-bang-tin" aria-label="Permalink to &quot;1. Desktop — tabs theo trạng thái + bảng tin&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/tin-cua-toi?status=all</span></div><div class="wf-body"><div class="wf-header"><span class="wf-logo">AnPhuc</span><span class="wf-nav"><span>Mua nhà</span><span>Đấu giá</span><span>Bảng gói</span><span>Hướng dẫn</span></span><span class="wf-header-actions"><span class="wf-bell">🔔<span class="count">2</span></span><span class="wf-avatar">NĐ</span></span></div><div class="wf-container"><div class="wf-breadcrumb">Dashboard › <b>Tin của tôi</b></div><div class="wf-row between middle" style="margin-bottom:10px;"><div class="wf-col" style="gap:2px;"><span class="wf-title xl">Tin của tôi</span><span class="wf-small">Hạn mức gói FREE: <b>1/2 tin đang bán</b> (đếm tin LISTED + RESERVED + SOLD trong 30 ngày) — <b class="wf-accent">Nâng cấp VIP để đăng thêm → SC-26</b> <span class="wf-callout">1</span></span></div><span class="wf-btn primary lg">＋ Đăng tin mới → SC-22</span></div><div class="wf-tabs"><span class="wf-tab active">Tất cả (4)</span><span class="wf-tab">DRAFT (1)</span><span class="wf-tab">IN_REVIEW (1)</span><span class="wf-tab">LISTED (1)</span><span class="wf-tab">RESERVED (0)</span><span class="wf-tab">SOLD (0)</span><span class="wf-tab">REJECTED (1) <span class="wf-callout danger">2</span></span></div><div class="wf-card flat" style="border-radius:0 10px 10px 10px;"><table class="wf-table"><thead><tr><th>Ảnh</th><th>Tin</th><th>Giá</th><th>Trạng thái</th><th>Cập nhật</th><th>Thao tác</th></tr></thead><tbody><tr><td><div class="wf-img" style="min-height:44px;width:64px;"><span>AB</span></div></td><td><b>Căn AB-05.02 — NOXH HP-380</b><br><span class="wf-small">72 m² · 2 PN · 1 WC · tầng 5 · Sổ hồng</span></td><td><span class="wf-money">1.250.000.000 ₫</span><br><span class="wf-small">17.361.111 ₫/m²</span></td><td><span class="wf-badge ok">LISTED — Đang bán</span></td><td><span class="wf-small">10/10/2026 08:15</span></td><td><span class="wf-btn sm">Rút tin <span class="wf-callout">3</span></span><span class="wf-btn sm ghost">Xem tin</span><span class="wf-btn sm ghost">Lịch sử duyệt</span></td></tr><tr><td><div class="wf-img" style="min-height:44px;width:64px;"><span>CT1</span></div></td><td><b>Căn CT1-B02.11 — NOXH HP-380</b><br><span class="wf-small">69,5 m² · 2 PN · tầng 2 · Sổ hồng</span></td><td><span class="wf-money">1.150.000.000 ₫</span><br><span class="wf-small">16.546.762 ₫/m²</span></td><td><span class="wf-badge info">IN_REVIEW — Chờ duyệt ≤24h</span> <span class="wf-callout">4</span></td><td><span class="wf-small">09/10/2026 14:02</span></td><td><span class="wf-btn sm ghost">Lịch sử duyệt</span><br><span class="wf-small wf-muted">🔒 không sửa được khi đang chờ duyệt</span></td></tr><tr><td><div class="wf-img" style="min-height:44px;width:64px;"><span>BA</span></div></td><td><b>Căn BA-07.01 — NOXH HP-380</b><br><span class="wf-small">65 m² · 2 PN · tầng 7 · Sổ hồng</span><br><span class="wf-small wf-danger-text">Lý do: &quot;Ảnh số 3 không thuộc căn đăng bán — chụp lại mặt trong căn hộ&quot; <span class="wf-callout danger">5</span></span></td><td><span class="wf-money">980.000.000 ₫</span><br><span class="wf-small">15.076.923 ₫/m²</span></td><td><span class="wf-badge danger">REJECTED — Bị từ chối</span></td><td><span class="wf-small">08/10/2026 16:40</span></td><td><span class="wf-btn sm primary">Sửa &amp; gửi lại</span><span class="wf-btn sm ghost">Lịch sử duyệt</span><br><span class="wf-small wf-muted">còn 4/5 lần gửi trong 30 ngày <span class="wf-callout warn">6</span></span></td></tr><tr><td><div class="wf-img" style="min-height:44px;width:64px;border-style:dashed;"><span>CD</span></div></td><td><b>Căn CD-03.06 — NOXH HP-380</b><br><span class="wf-small">60 m² · 2 PN · tầng 3 · nháp lưu 07/10/2026</span></td><td><span class="wf-small wf-muted">chưa nhập giá</span></td><td><span class="wf-badge muted">DRAFT — Nháp</span></td><td><span class="wf-small">07/10/2026 21:05</span></td><td><span class="wf-btn sm primary">Sửa tiếp</span><span class="wf-btn sm">Gửi duyệt</span><span class="wf-btn sm ghost">Lịch sử duyệt</span></td></tr></tbody></table></div><div class="wf-row wrap middle" style="margin-top:10px;gap:8px;"><span class="wf-small wf-strong">Bộ badge chuẩn (màu theo enum docs/07 §3) <span class="wf-callout">7</span>:</span><span class="wf-badge muted">DRAFT</span><span class="wf-badge info">IN_REVIEW</span><span class="wf-badge ok">LISTED</span><span class="wf-badge warn">RESERVED</span><span class="wf-badge muted">SOLD</span><span class="wf-badge danger">REJECTED</span><span class="wf-badge muted">WITHDRAWN</span></div></div><div class="wf-footer"><span>AnPhucRealEstate — sàn NOXH được vận hành bởi An Phuc</span><span>Quy chế đấu giá</span><span>CSKH 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích hành vi (trace: docs/05 §3 SC-23 · docs/03 UC-05 · docs/08 BR-HS)</div><ol><li><span class="num">1</span><span><b>Quota hiện công khai trên đầu bảng</b>: đếm tin state ∈ {LISTED, RESERVED} hoặc SOLD trong 30 ngày gần nhất (không đếm DRAFT/IN_REVIEW/REJECTED/WITHDRAWN). Chạm hạn khi gửi duyệt → 422 <code>LISTING_QUOTA_EXCEEDED</code>, message nguyên văn: &quot;Bạn đã dùng {used}/{limit} tin. Nâng cấp VIP để đăng thêm&quot; → modal upsell VIP (SC-26/UC-05 AF-1) — enforce lúc submit, không cắt tin đang sống. <span class="ref">BR-PKG-02</span> <span class="ref">FR-HS-10</span> <span class="ref">docs/06 §5</span></span></li><li><span class="num">2</span><span><b>Tabs = filter trạng thái, sync URL</b> <code>?status=</code> (shareable, reload giữ tab); dữ liệu từ <code>GET /users/me/housing?status=</code>. Tab REJECTED có chấm đỏ khi còn tin chưa xử lý — không để tin bị từ chối &quot;chìm&quot; im lặng. <span class="ref">FR-HS-09</span> <span class="ref">docs/05 §3 SC-23</span></span></li><li><span class="num">3</span><span><b>Thao tác theo trạng thái</b> (state machine docs/08 §10.1): DRAFT/REJECTED → &quot;Sửa&quot; (+ &quot;Gửi duyệt&quot;); LISTED → &quot;Rút tin&quot; + &quot;Xem tin&quot;; IN_REVIEW → khóa sửa (muốn đổi phải chờ kết quả); RESERVED/SOLD → khóa mọi sửa/rút (&quot;Xem phiên&quot;/&quot;Xem tin&quot; mà thôi). Nút không hợp lệ bị ẩn/disable kèm 🔒 giải thích — không hiện để rồi báo lỗi. <span class="ref">FR-HS-03</span> <span class="ref">BR-HS-11</span> <span class="ref">docs/08 §10.1</span></span></li><li><span class="num">4</span><span>IN_REVIEW kèm nhãn SLA &quot;Chờ duyệt ≤24h giờ làm việc&quot; — quá hạn, dòng tự thêm badge warn &quot;quá SLA — liên hệ CSKH&quot; (đối soát <code>submittedAt</code>). <span class="ref">BR-ADM-03</span></span></li><li><span class="num">5</span><span><b>Lý do REJECTED hiển thị nguyên văn</b> ngay trong row (cắt 2 dòng, chấm &quot;…&quot; — full text trong drawer lịch sử, mục 3). Reason do ADMIN nhập 10–500 ký tự, FE không viết lại. <span class="ref">BR-HS-08</span></span></li><li><span class="num">6</span><span>Đếm <b>5 lần gửi/30 ngày rolling</b> hiện cạnh nút &quot;Sửa &amp; gửi lại&quot;; chạm trần → 422 <code>RESUBMIT_LIMIT</code> message nguyên văn: &quot;Vượt giới hạn 5 lần gửi/30 ngày — liên hệ CS&quot;, nút gửi disable. <span class="ref">BR-HS-09</span> <span class="ref">FR-HS-04</span> <span class="ref">docs/06 §5</span></span></li><li><span class="num">7</span><span>Badge dùng component <code>StatusBadge</code> chung toàn site, màu map từ enum docs/07 §3 (DRAFT/WITHDRAWN/SOLD = muted · IN_REVIEW = info · LISTED = ok · RESERVED = warn · REJECTED = danger). Nhãn tiếng Việt cạnh mã enum ở màn của owner (user nội bộ hiểu vòng đời); màn public chỉ hiện nhãn Việt. <span class="ref">docs/05 §6</span> <span class="ref">docs/07 §3</span></span></li></ol></div><h2 id="_2-modal-xac-nhan-rut-tin-—-hanh-đong-vinh-vien" tabindex="-1">2. Modal xác nhận &quot;Rút tin&quot; — hành động vĩnh viễn <a class="header-anchor" href="#_2-modal-xac-nhan-rut-tin-—-hanh-đong-vinh-vien" aria-label="Permalink to &quot;2. Modal xác nhận &quot;Rút tin&quot; — hành động vĩnh viễn&quot;">​</a></h2><div class="wf"><div class="wf-modal-overlay"><div class="wf-modal"><div class="head">Rút tin — không thể hoàn tác <span class="wf-callout danger">8</span></div><div class="wf-col" style="margin:10px 0;gap:6px;"><div class="wf-row between"><span class="wf-text">Tin rút</span><span class="wf-strong">Căn AB-05.02 — NOXH HP-380</span></div><div class="wf-row between"><span class="wf-text">Giá đang rao</span><span class="wf-money">1.250.000.000 ₫</span></div><div class="wf-row between"><span class="wf-text">Đang hiển thị từ</span><span class="wf-strong">10/10/2026 08:15 (GMT+7)</span></div><div class="wf-row between"><span class="wf-text">Trạng thái sau khi rút</span><span class="wf-badge muted">WITHDRAWN (vĩnh viễn)</span></div></div><div class="wf-note" style="background:var(--wf-danger-soft);border-color:var(--wf-danger);color:var(--wf-danger);"> Tin sẽ <b>biến mất khỏi sàn ngay lập tức</b> và chuyển sang WITHDRAWN — trạng thái kết thúc, <b>không thể khôi phục hay đăng lại từ tin này</b>. Muốn bán tiếp phải tạo tin mới và chờ duyệt lại từ đầu (tính vào hạn mức + số lần gửi). </div><span class="wf-small">Tin đang có người đặt lịch xem? Rút tin sẽ tự hủy các lịch chờ — chủ nhà nên phản hồi lịch trước khi rút (SC-27).</span><div class="wf-row" style="margin-top:12px;"><span class="wf-btn" style="flex:1;">Hủy — giữ tin</span><span class="wf-btn danger" style="flex:1;">XÁC NHẬN RÚT TIN</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích rút tin</div><ol><li><span class="num">8</span><span>Rút tin (<code>POST /housing/{id}/withdraw</code>) chỉ áp dụng cho LISTED → WITHDRAWN (terminal). Confirm dialog bắt buộc, nêu <b>hậu quả thật</b> (mất gì, phải làm lại gì) — cùng nguyên tắc modal bid SC-06. Đang gửi: nút danger loading disabled; 409 <code>LISTING_LOCKED</code> (tin vừa vào phiên đấu giá) → toast: &quot;Tin đang tham gia đấu giá — không thể rút&quot; + link xem phiên. RESERVED/SOLD: không có nút rút ngay từ bảng. <span class="ref">FR-HS-05</span> <span class="ref">BR-HS-11</span> <span class="ref">docs/08 §10.1</span></span></li></ol></div><h2 id="_3-drawer-lich-su-duyet-—-timeline-ly-do-tu-choi-đay-đu" tabindex="-1">3. Drawer &quot;Lịch sử duyệt&quot; — timeline + lý do từ chối đầy đủ <a class="header-anchor" href="#_3-drawer-lich-su-duyet-—-timeline-ly-do-tu-choi-đay-đu" aria-label="Permalink to &quot;3. Drawer &quot;Lịch sử duyệt&quot; — timeline + lý do từ chối đầy đủ&quot;">​</a></h2><div class="wf"><div class="wf-row" style="justify-content:center;gap:20px;flex-wrap:wrap;"><div class="wf-drawer"><div class="wf-row between middle"><span class="wf-title">Lịch sử duyệt — Căn BA-07.01 <span class="wf-callout">9</span></span><span class="wf-btn sm ghost">✕</span></div><div class="wf-row middle" style="gap:6px;margin:8px 0;"><span class="wf-badge danger">REJECTED</span><span class="wf-small">lần gửi 1/5 trong 30 ngày</span></div><div class="wf-col" style="gap:0;"><div class="wf-row between"><span class="wf-small"><b>08/10/2026 16:40</b> — ADMIN từ chối</span><span class="wf-badge danger">REJECT</span></div><div class="wf-note" style="background:var(--wf-danger-soft);border-color:var(--wf-danger);color:var(--wf-danger);margin:6px 0 12px;">Lý do (nguyên văn): &quot;Ảnh số 3 không thuộc căn đăng bán — chụp lại mặt trong căn hộ&quot;</div><div class="wf-row between"><span class="wf-small"><b>08/10/2026 10:20</b> — Bạn gửi duyệt lần 1</span><span class="wf-badge info">SUBMIT</span></div><div style="height:12px;"></div><div class="wf-row between"><span class="wf-small"><b>07/10/2026 20:55</b> — Bạn tạo nháp + upload 6 ảnh, 2 PDF</span><span class="wf-badge muted">DRAFT</span></div></div><span class="wf-btn primary block" style="margin-top:12px;">Sửa theo góp ý &amp; gửi lại → SC-22</span><span class="wf-small wf-muted" style="display:block;margin-top:8px;">Mỗi lần gửi lại = duyệt lại từ đầu (không &quot;duyệt nhanh&quot;). Còn 4/5 lần trong 30 ngày — quá giới hạn: &quot;Vượt giới hạn 5 lần gửi/30 ngày — liên hệ CS&quot;. <span class="wf-callout warn">10</span></span></div><div class="wf-col" style="max-width:320px;gap:10px;"><span class="wf-state-label">TRẠNG THÁI: LISTED — LỊCH SỬ DUYỆT THÀNH CÔNG</span><div class="wf-drawer" style="width:320px;"><span class="wf-title">Lịch sử duyệt — Căn AB-05.02</span><div class="wf-row middle" style="gap:6px;margin:8px 0;"><span class="wf-badge ok">LISTED</span><span class="wf-small">duyệt trong 18 giờ (SLA ≤24h)</span></div><div class="wf-col" style="gap:0;"><div class="wf-row between"><span class="wf-small"><b>10/10/2026 08:15</b> — ADMIN duyệt: tin lên sàn</span><span class="wf-badge ok">APPROVE</span></div><div style="height:12px;"></div><div class="wf-row between"><span class="wf-small"><b>09/10/2026 14:02</b> — Bạn gửi duyệt</span><span class="wf-badge info">SUBMIT</span></div></div><span class="wf-small wf-muted" style="display:block;margin-top:10px;">Tin LISTED có thể được ADMIN đưa vào phiên đấu giá → tự chuyển RESERVED (chủ nhà nhận 🔔, không tự thao tác được nữa).</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích drawer lịch sử</div><ol><li><span class="num">9</span><span>Drawer mở từ nút &quot;Lịch sử duyệt&quot; của mọi row (desktop: phải; mobile: full-screen sheet). Timeline đầy đủ: tạo nháp → mỗi lần submit → mỗi quyết định (APPROVE/REJECT kèm reason nguyên văn, người duyệt hiển thị &quot;ADMIN&quot; — không lộ danh tính nhân sự). <span class="ref">BR-HS-07/08</span> <span class="ref">FR-NTF-01</span></span></li><li><span class="num">10</span><span>Reject không xóa tin: user sửa từ chính tin REJECTED rồi submit lại (quay về IN_REVIEW), đếm vào giới hạn 5 lần/30 ngày; sau reject, tin KHÔNG tự hiển thị public. <span class="ref">docs/08 §10.1</span> <span class="ref">BR-HS-09</span> <span class="ref">UC-05 EF-3</span></span></li></ol></div><h2 id="_4-trang-thai-rong-empty-—-2-bien-the" tabindex="-1">4. Trạng thái rỗng (empty) — 2 biến thể <a class="header-anchor" href="#_4-trang-thai-rong-empty-—-2-bien-the" aria-label="Permalink to &quot;4. Trạng thái rỗng (empty) — 2 biến thể&quot;">​</a></h2><div class="wf"><div class="wf-grid"><div class="wf-col"><span class="wf-state-label">EMPTY: CHƯA CÓ TIN NÀO (KYC ĐÃ APPROVED)</span><div class="wf-card"><div class="pad"><div class="wf-empty"><span class="icon">🏠</span><b>Bạn chưa có tin đăng nào</b><div class="wf-small" style="margin:6px 0 12px;">Gói FREE cho phép 2 tin đang bán — đăng tin đầu tiên, ADMIN duyệt trong ≤24 giờ làm việc.</div><span class="wf-btn primary lg">ĐĂNG TIN ĐẦU TIÊN → SC-22 <span class="wf-callout">11</span></span></div></div></div></div><div class="wf-col"><span class="wf-state-label">EMPTY: KYC CHƯA APPROVED (CHẶN TỪ GỐC)</span><div class="wf-card"><div class="pad"><div class="wf-empty"><span class="icon">🪪</span><b>Cần xác minh danh tính trước khi đăng tin</b><div class="wf-small" style="margin:6px 0 12px;">Bạn cần xác minh danh tính (CCCD) trước khi thao tác này</div><span class="wf-btn primary lg">XÁC MINH NGAY → SC-21</span></div><span class="wf-small wf-muted" style="display:block;margin-top:8px;">Nút &quot;Đăng tin mới&quot; trên đầu trang disable kèm 🔒 — CTA duy nhất là xác minh (KYC là điều kiện tiên quyết tạo tin).</span></div></div></div><div class="wf-col"><span class="wf-state-label">EMPTY THEO TAB: TAB KHÔNG CÓ TIN</span><div class="wf-card"><div class="pad"><div class="wf-tabs" style="margin-bottom:10px;"><span class="wf-tab">Tất cả (4)</span><span class="wf-tab active">SOLD (0)</span><span class="wf-tab">REJECTED (1)</span></div><div class="wf-empty" style="padding:20px;"><b>Không có tin ở trạng thái này</b><div class="wf-small" style="margin-top:4px;">Lọc theo tab khác hoặc xem tất cả</div></div></div></div></div><div class="wf-col"><span class="wf-state-label">LOADING (SKELETON) + ERROR</span><div class="wf-col" style="gap:10px;"><div class="wf-skeleton" style="height:36px;"></div><div class="wf-skeleton" style="height:56px;"></div><div class="wf-skeleton" style="height:56px;"></div><div class="wf-skeleton" style="height:56px;"></div><div class="wf-error-box"><b>Không tải được danh sách tin</b><div class="wf-small" style="margin:6px 0;">Kiểm tra kết nối rồi thử lại — nếu lỗi lặp lại, báo CSKH 1900-xxx kèm mã:</div><span class="wf-trace">traceId: 77b2…9ae0</span><div style="margin-top:10px;"><span class="wf-btn primary sm">Thử lại <span class="wf-callout">12</span></span></div></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích empty / skeleton / error</div><ol><li><span class="num">11</span><span>Empty-state phân nhánh theo KYC: APPROVED → CTA đăng tin; chưa APPROVED → copy <code>KYC_REQUIRED</code> nguyên văn docs/06 §5 + CTA duy nhất về SC-21 (không cho bấm đăng tin để rồi nhận 403). <span class="ref">BR-KYC-08</span> <span class="ref">UC-05 EF-1</span> <span class="ref">docs/06 §5</span></span></li><li><span class="num">12</span><span>4 trạng thái nền: <b>Loading</b> = skeleton tabs + 4 row (không spinner toàn trang); <b>Error</b> = hộp lỗi + traceId + &quot;Thử lại&quot;; <b>Empty</b> = 2 biến thể trên; <b>Data</b> = mục 1. Thao tác mutation (rút tin/gửi duyệt) thất bại → toast tại chỗ, bảng tự refresh giữ nguyên tab. <span class="ref">docs/05 §1.4</span></span></li></ol></div><h2 id="_5-mobile-360px-—-card-thay-cho-bang" tabindex="-1">5. Mobile 360px — card thay cho bảng <a class="header-anchor" href="#_5-mobile-360px-—-card-thay-cho-bang" aria-label="Permalink to &quot;5. Mobile 360px — card thay cho bảng&quot;">​</a></h2><div class="wf"><div class="wf-row" style="justify-content:center;gap:20px;flex-wrap:wrap;"><div><span class="wf-state-label">MOBILE — DANH SÁCH TIN (CARD)</span><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-header" style="padding:8px 12px;"><span class="wf-logo">AnPhuc</span><span class="wf-header-actions"><span class="wf-bell">🔔<span class="count">2</span></span><span class="wf-avatar">NĐ</span></span></div><div class="wf-tabs"><span class="wf-tab active">Tất cả (4)</span><span class="wf-tab">LISTED (1)</span><span class="wf-tab">REJECTED (1)</span><span class="wf-tab">…cuộn ngang</span></div><div class="wf-container" style="padding:12px;"><div class="wf-col" style="gap:10px;"><span class="wf-btn primary block">＋ Đăng tin mới</span><span class="wf-small">FREE 1/2 tin đang bán · <b class="wf-accent">Nâng VIP →</b></span><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><div class="wf-row" style="gap:10px;"><div class="wf-img" style="min-height:56px;width:72px;flex:none;"><span>AB</span></div><div class="wf-grow wf-col" style="gap:2px;"><span class="wf-title">Căn AB-05.02 — NOXH HP-380</span><span class="wf-money">1.250.000.000 ₫</span><span class="wf-badge ok">LISTED — Đang bán</span></div></div><div class="wf-row" style="gap:6px;"><span class="wf-btn sm">Rút tin</span><span class="wf-btn sm ghost">Xem tin</span><span class="wf-btn sm ghost">Lịch sử</span></div></div></div><div class="wf-card" style="border-color:var(--wf-danger);"><div class="pad wf-col" style="gap:8px;"><div class="wf-row" style="gap:10px;"><div class="wf-img" style="min-height:56px;width:72px;flex:none;"><span>BA</span></div><div class="wf-grow wf-col" style="gap:2px;"><span class="wf-title">Căn BA-07.01 — NOXH HP-380</span><span class="wf-badge danger">REJECTED — Bị từ chối</span></div></div><span class="wf-small wf-danger-text">&quot;Ảnh số 3 không thuộc căn đăng bán — chụp lại mặt trong căn hộ&quot;</span><div class="wf-row between middle" style="gap:6px;"><span class="wf-btn sm primary">Sửa &amp; gửi lại</span><span class="wf-small wf-muted">còn 4/5 lần · 30 ngày</span></div></div></div></div></div></div></div><div><span class="wf-state-label">MOBILE — XÁC NHẬN RÚT TIN (BOTTOM SHEET)</span><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div style="flex:1;background:rgba(0,0,0,0.06);padding:12px;min-height:300px;display:flex;align-items:flex-end;"><div class="wf-card" style="width:100%;border-radius:12px 12px 0 0;"><div class="pad wf-col" style="gap:10px;"><span class="wf-title">Rút tin — không thể hoàn tác</span><div class="wf-row between"><span class="wf-text">Căn AB-05.02</span><span class="wf-money">1.250.000.000 ₫</span></div><div class="wf-note" style="background:var(--wf-danger-soft);border-color:var(--wf-danger);color:var(--wf-danger);">Tin biến mất khỏi sàn ngay, chuyển WITHDRAWN vĩnh viễn — muốn bán tiếp phải tạo tin mới, duyệt lại từ đầu.</div><span class="wf-btn danger block">XÁC NHẬN RÚT TIN</span><span class="wf-btn ghost block">Hủy — giữ tin</span></div></div></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích mobile</div><ol><li><span class="num">M</span><span>Bảng → card xếp dọc (thumb trái, badge + giá phải, action row dưới); tabs cuộn ngang giữ thứ tự trạng thái; confirm rút tin là bottom-sheet (nút Hủy to, đặt dưới — khó bấm nhầm hơn). Row REJECTED viền đỏ + reason cắt 2 dòng, chạm để mở drawer lịch sử đầy đủ.</span></li></ol></div><h2 id="_6-checklist-designer-khi-dung-figma-cho-sc-23" tabindex="-1">6. Checklist designer khi dựng Figma cho SC-23 <a class="header-anchor" href="#_6-checklist-designer-khi-dung-figma-cho-sc-23" aria-label="Permalink to &quot;6. Checklist designer khi dựng Figma cho SC-23&quot;">​</a></h2><ul><li>[ ] Đủ layout: desktop (tabs + table 6 cột) / mobile 360 (card + tabs cuộn ngang) / tablet 768 (ẩn cột Ảnh + Giá gộp vào tiêu đề)</li><li>[ ] Đủ 7 badge trạng thái theo enum docs/07 §3: DRAFT · IN_REVIEW · LISTED · RESERVED · SOLD · REJECTED · WITHDRAWN — màu map StatusBadge dùng chung</li><li>[ ] Thao tác theo state machine: Sửa chỉ DRAFT/REJECTED · Rút tin chỉ LISTED (confirm vĩnh viễn) · IN_REVIEW/RESERVED/SOLD khóa kèm 🔒 giải thích · mọi row có &quot;Lịch sử duyệt&quot;</li><li>[ ] Drawer lịch sử: timeline tạo nháp → submit → quyết định; reason REJECT nguyên văn 10–500 ký tự; đếm lần gửi x/5 (30 ngày)</li><li>[ ] Quota header <code>1/2 tin</code> đúng quy tắc đếm BR-PKG-02; link upsell VIP (500.000 ₫ VIP_STANDARD / 1.500.000 ₫ VIP_PRO)</li><li>[ ] Copy đúng nguyên văn docs/06 §5: &quot;Vượt giới hạn 5 lần gửi/30 ngày — liên hệ CS&quot; · &quot;Bạn đã dùng {used}/{limit} tin. Nâng cấp VIP để đăng thêm&quot; · &quot;Bạn cần xác minh danh tính (CCCD) trước khi thao tác này&quot;</li><li>[ ] Tiền <code>1.250.000.000 ₫</code>; ngày <code>dd/MM/yyyy HH:mm</code> (GMT+7); skeleton 4 row + error box traceId</li><li>[ ] Không emoji icon trong UI production (🔒/🏠/🪪/✕ trong wireframe là placeholder vị trí — thay icon set thật)</li><li>[ ] Accessibility: table có caption + scope cột; tabs role tablist, chuyển bằng phím; confirm modal focus vào nút &quot;Hủy&quot; trước (chống rút tin nhầm); contrast AA badge</li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ (vd số lần gửi lại, quota, rút tin) cần PM duyệt trên docs/08 trước.</p></div>',21)])])}const w=a(l,[["render",c]]);export{g as __pageData,w as default};
